CREATE TABLE editions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, year INTEGER NOT NULL, name VARCHAR(160) NOT NULL, locality VARCHAR(160) NOT NULL, starts_on DATE, ends_on DATE, status VARCHAR(20) NOT NULL DEFAULT 'PREPARATION', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE edition_access (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, edition_id BIGINT NOT NULL, user_id BIGINT NOT NULL, team_id BIGINT, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_edition_access UNIQUE (edition_id, user_id));
INSERT INTO editions(year, name, locality, status) VALUES (2026, 'Edição atual', 'Localidade atual', 'ACTIVE');
ALTER TABLE teams ADD COLUMN edition_id BIGINT;
ALTER TABLE household_visits ADD COLUMN edition_id BIGINT;
ALTER TABLE territories ADD COLUMN edition_id BIGINT;
UPDATE teams SET edition_id = (SELECT id FROM editions WHERE status = 'ACTIVE');
UPDATE household_visits SET edition_id = (SELECT id FROM editions WHERE status = 'ACTIVE');
UPDATE territories SET edition_id = (SELECT id FROM editions WHERE status = 'ACTIVE');
INSERT INTO edition_access(edition_id, user_id, team_id) SELECT e.id, u.id, u.team_id FROM editions e CROSS JOIN app_users u;
ALTER TABLE teams DROP CONSTRAINT IF EXISTS teams_name_key;
CREATE UNIQUE INDEX uq_teams_edition_name ON teams(edition_id, name);
